const FloatingHashtag: React.FC<{
  tag: string; x: number; y: number; size: number; color: string; delay: number;
}> = ({ tag, x, y, size, color, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const float = Math.sin((frame + delay * 10) / 18) * 12;

  return (
    <div
      style={{
        position: "absolute",
        left: `${x}%`,
        top: `${y}%`,
        fontSize: size,
        fontWeight: 800,
        color,
        opacity: interpolate(progress, [0, 1], [0, 0.85]),
        transform: `translateY(${interpolate(progress, [0, 1], [40, float])}px) scale(${interpolate(progress, [0, 1], [0.7, 1])})`,
        letterSpacing: "-0.02em",
        whiteSpace: "nowrap",
        textShadow: `0 0 40px ${color}44`,
      }}
    >
      {tag}
    </div>
  );
};

